import { deriveHouseholdOperation, type HouseholdOperationAction } from './operations';
import type { AdviceResult } from './rebalance';
import type { LocalPortfolio, PublicSnapshot } from './types';

export type HouseholdDecisionKey =
  | 'DATA_BLOCKED'
  | 'NEED_HOLDINGS'
  | 'ACTION_REQUIRED'
  | 'AWAITING_EXECUTION'
  | 'READY_NO_TRADE'
  | 'MONTH_COMPLETE';

export type HouseholdActionTarget =
  | 'DATA_ISSUES'
  | 'HOLDINGS_EDITOR'
  | 'ADVICE_REVIEW'
  | 'EXECUTION_RECORD'
  | 'MONTHLY_REVIEW'
  | 'MONTH_RECORD';

export interface HouseholdDecisionState {
  key: HouseholdDecisionKey;
  title: string;
  detail: string;
  action: HouseholdOperationAction;
  actionLabel: string;
  actionTarget: HouseholdActionTarget;
  actionConsequence: string;
  focusCode?: string;
  tone: 'positive' | 'warning' | 'negative' | 'neutral';
  completed: number;
  total: number;
}

export function effectiveDecisionLog(snapshot: PublicSnapshot): PublicSnapshot['decisionLog'] {
  const bySignalDate = new Map<string, PublicSnapshot['decisionLog'][number]>();
  const byId = new Map<string, PublicSnapshot['decisionLog'][number]>();
  snapshot.decisionLog.forEach((entry) => {
    const signalDate = entry.signalDate ?? entry.date;
    if (entry.decisionId) byId.set(entry.decisionId, entry);
    if (entry.decisionType === 'LEGACY_UNVERIFIED') {
      if (!bySignalDate.has(signalDate)) bySignalDate.set(signalDate, entry);
      return;
    }
    if (entry.decisionType !== 'CORRECTION') {
      bySignalDate.set(signalDate, entry);
      return;
    }
    const replacement = entry.replacement;
    if (replacement) {
      const target = (entry.correctsDecisionId && byId.get(entry.correctsDecisionId))
        ?? bySignalDate.get(signalDate);
      if (target) bySignalDate.set(signalDate, { ...target, ...replacement, decisionType: 'CORRECTION' });
      return;
    }
    if (Number.isFinite(entry.riskScore) && entry.targetWeights) bySignalDate.set(signalDate, entry);
  });
  return [...bySignalDate.values()].sort((left, right) => (
    (left.signalDate ?? left.date).localeCompare(right.signalDate ?? right.date)
  ));
}

export function confirmedRiskRegime(snapshot: PublicSnapshot): PublicSnapshot['risk']['regime'] {
  const confirmed = effectiveDecisionLog(snapshot)
    .filter((entry) => (entry.signalDate ?? entry.date) === snapshot.meta.confirmedSignalDate)
    .at(-1)?.riskRegime;
  return (confirmed as PublicSnapshot['risk']['regime'] | undefined) ?? snapshot.risk.regime;
}

export function deriveHouseholdDecision(
  snapshot: PublicSnapshot,
  portfolio: LocalPortfolio,
  advice: AdviceResult,
): HouseholdDecisionState {
  const operation = deriveHouseholdOperation(snapshot, portfolio, advice);
  const activeRows = advice.rows.filter((row) => row.action !== 'NO TRADE');
  const current = operation.current;
  const base = {
    action: current.action,
    completed: operation.completed,
    total: operation.total,
  };

  if (current.status === 'BLOCKED' || snapshot.health.blocking) {
    return {
      ...base,
      key: 'DATA_BLOCKED',
      title: '数据异常，暂停新的建议',
      detail: snapshot.health.summary,
      actionLabel: '查看阻断原因',
      actionTarget: 'DATA_ISSUES',
      actionConsequence: '历史目标继续只读；数据恢复前不能保存新的人工计划。',
      tone: 'negative',
    };
  }

  if (current.key === 'HOLDINGS') {
    return {
      ...base,
      key: 'NEED_HOLDINGS',
      title: advice.available ? '持仓已过期，需要更新' : '更新持仓与现金',
      detail: current.detail,
      actionLabel: '更新持仓与现金',
      actionTarget: 'HOLDINGS_EDITOR',
      actionConsequence: '更新只保存在当前浏览器，用于重算偏差，不会提交交易。',
      tone: 'warning',
    };
  }

  if (operation.completed === operation.total) {
    return {
      ...base,
      key: 'MONTH_COMPLETE',
      title: '本月已经完成',
      detail: '保持当前组合，等待下一次月末确认。',
      actionLabel: '查看本月记录',
      actionTarget: 'MONTH_RECORD',
      actionConsequence: '只查看本月只读留痕，不会重新生成或保存同月建议。',
      tone: 'positive',
    };
  }

  if (current.key === 'ADVICE' && activeRows.length > 0) {
    return {
      ...base,
      key: 'ACTION_REQUIRED',
      title: '本月计划需要复核',
      detail: '偏离已越过免交易带；请核对本月计划、交易成本和计划后偏差。',
      actionLabel: '核对本月人工计划',
      actionTarget: 'ADVICE_REVIEW',
      actionConsequence: `将查看 ${activeRows.length} 只需行动 ETF；此步骤不会保存计划或提交交易。`,
      tone: 'warning',
    };
  }

  if (current.key === 'EXECUTION') {
    return {
      ...base,
      key: 'AWAITING_EXECUTION',
      title: '等待登记实际结果',
      detail: current.detail,
      actionLabel: '登记成交或跳过',
      actionTarget: 'EXECUTION_RECORD',
      actionConsequence: '请先在券商自行操作；登记只更新本机持仓、现金和审计留痕。',
      tone: 'neutral',
    };
  }

  if (current.key === 'REVIEW') {
    return {
      ...base,
      key: 'READY_NO_TRADE',
      title: activeRows.length > 0 ? '执行结果已留痕' : '本月无需调仓',
      detail: activeRows.length > 0
        ? '实际结果已经登记；完成月度复盘后等待下次月末确认。'
        : '当前偏差仍在免交易带内；完成月度复盘后等待下次月末确认。',
      actionLabel: '完成本月复盘',
      actionTarget: 'MONTHLY_REVIEW',
      actionConsequence: '完成复盘只保存本机检查记录，不会产生买卖操作。',
      tone: 'positive',
    };
  }

  return {
    ...base,
    key: 'READY_NO_TRADE',
    title: '本月无需调仓',
    detail: '当前偏差仍在免交易带内；完成月度复盘后等待下次月末确认。',
    actionLabel: '完成本月复盘',
    actionTarget: 'MONTHLY_REVIEW',
    actionConsequence: '完成复盘只保存本机检查记录，不会产生买卖操作。',
    tone: 'positive',
  };
}
