import { ASSET_CODES, type AssetCode, type CostBasisStatus, type LocalPortfolio, type PublicAsset } from './types';
import { migratePortfolio } from './portfolio-ledger';

export type ValuationQuality = 'CONFIRMED' | 'ESTIMATED' | 'UNAVAILABLE';

export interface AssetValuation {
  code: AssetCode;
  value: number | null;
  weight: number | null;
  asOf: string | null;
  quality: ValuationQuality;
  issue: string | null;
}

export interface LocalValuation {
  asOf: string | null;
  valuationDates: string[];
  dateConsistent: boolean;
  valuesByCode: Record<AssetCode, number>;
  rows: Record<AssetCode, AssetValuation>;
  totalInvested: number;
  cash: number;
  totalAssets: number;
  currentWeights: Record<AssetCode, number>;
  currentEquity: number;
  currentDefense: number;
  cashWeight: number;
  coverage: number;
  quality: ValuationQuality;
  issues: string[];
}

export interface AssetProfitLoss {
  code: AssetCode;
  marketValue: number | null;
  remainingCostBasis: number | null;
  averageCost: number | null;
  amount: number | null;
  returnValue: number | null;
  realizedProfit: number | null;
  income: number;
  totalInvestmentProfit: number | null;
  quality: CostBasisStatus;
  updatedAt: string | null;
  issue: string | null;
}

export interface PortfolioProfitLoss {
  rows: Record<AssetCode, AssetProfitLoss>;
  coverage: number;
  coveredMarketValue: number;
  coveredCostBasis: number;
  coveredProfit: number;
  realizedProfit: number;
  income: number;
  totalProfit: number | null;
  totalInvestmentProfit: number | null;
  quality: CostBasisStatus;
  latestCostBasisUpdate: string | null;
}

export interface DisplayTargetAmounts {
  amountsByCode: Record<AssetCode, number>;
  roundingAdjustment: number;
  adjustmentCode: AssetCode;
}

function validNonNegative(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0;
}

function assetValuation(code: AssetCode, portfolio: LocalPortfolio, asset?: PublicAsset): AssetValuation {
  const position = portfolio.positionsByCode?.[code];
  const fallback = portfolio.values[code] ?? 0;
  if (!position) {
    return {
      code, value: validNonNegative(fallback) ? fallback : null, weight: null,
      asOf: portfolio.updatedAt?.slice(0, 10) ?? null,
      quality: validNonNegative(fallback) ? 'ESTIMATED' : 'UNAVAILABLE',
      issue: validNonNegative(fallback) ? '沿用最近确认市值' : '缺少持仓记录',
    };
  }
  if (position.inputMode === 'QUANTITY') {
    const quantity = position.quantity;
    const price = asset?.valuationClose;
    if (!validNonNegative(quantity)) return { code, value: null, weight: null, asOf: null, quality: 'UNAVAILABLE', issue: '份额无效' };
    if (quantity === 0 && validNonNegative(fallback) && fallback > 0 && !position.confirmedAt) {
      return { code, value: fallback, weight: null, asOf: portfolio.updatedAt?.slice(0, 10) ?? null, quality: 'ESTIMATED', issue: '沿用旧账本确认市值' };
    }
    if (quantity === 0) return { code, value: 0, weight: null, asOf: asset?.valuationPriceDate ?? null, quality: 'CONFIRMED', issue: null };
    if (price == null || !Number.isFinite(price) || price <= 0) return { code, value: null, weight: null, asOf: null, quality: 'UNAVAILABLE', issue: '缺少未复权估值价' };
    return { code, value: quantity * price, weight: null, asOf: asset?.valuationPriceDate ?? null, quality: 'CONFIRMED', issue: null };
  }
  const confirmed = position.confirmedMarketValue;
  if (!validNonNegative(confirmed)) return { code, value: null, weight: null, asOf: null, quality: 'UNAVAILABLE', issue: '确认市值无效' };
  if (confirmed === 0 && validNonNegative(fallback) && fallback > 0 && !position.confirmedAt) {
    return { code, value: fallback, weight: null, asOf: portfolio.updatedAt?.slice(0, 10) ?? null, quality: 'ESTIMATED', issue: '沿用旧账本确认市值' };
  }
  if (confirmed === 0) return { code, value: 0, weight: null, asOf: position.valuationPriceDate ?? position.confirmedAt?.slice(0, 10) ?? null, quality: 'CONFIRMED', issue: null };
  const anchor = position.valuationPriceAtConfirmation;
  const latest = asset?.valuationClose;
  if (anchor != null && Number.isFinite(anchor) && anchor > 0 && latest != null && Number.isFinite(latest) && latest > 0) {
    return {
      code, value: confirmed * latest / anchor, weight: null,
      asOf: asset?.valuationPriceDate ?? null, quality: 'ESTIMATED', issue: '市值按未复权价格变化估算',
    };
  }
  if (anchor != null && Number.isFinite(anchor) && anchor > 0) {
    return { code, value: null, weight: null, asOf: null, quality: 'UNAVAILABLE', issue: '缺少最新未复权估值价' };
  }
  return {
    code, value: confirmed, weight: null,
    asOf: position.confirmedAt?.slice(0, 10) ?? portfolio.updatedAt?.slice(0, 10) ?? null,
    quality: 'ESTIMATED', issue: '缺少确认估值锚点，沿用最近确认市值',
  };
}

export function calculateLocalValuation(rawPortfolio: LocalPortfolio, assets: PublicAsset[]): LocalValuation {
  const portfolio = migratePortfolio(rawPortfolio);
  const rows = {} as Record<AssetCode, AssetValuation>;
  const valuesByCode = {} as Record<AssetCode, number>;
  const issues: string[] = [];
  let availableValue = 0;
  let expectedValue = 0;
  ASSET_CODES.forEach((code) => {
    const row = assetValuation(code, portfolio, assets.find((asset) => asset.code === code));
    rows[code] = row;
    valuesByCode[code] = row.value ?? 0;
    if (row.value != null) availableValue += row.value;
    expectedValue += Math.max(row.value ?? 0, validNonNegative(portfolio.values[code]) ? portfolio.values[code]! : 0);
    const position = portfolio.positionsByCode?.[code];
    const recordedAmount = position?.inputMode === 'QUANTITY' ? position.quantity : position?.confirmedMarketValue;
    if (row.issue && ((row.value ?? 0) > 0 || (portfolio.values[code] ?? 0) > 0 || (recordedAmount ?? 0) > 0)) {
      issues.push(`${code} ${row.issue}`);
    }
  });
  const cash = Math.max(0, Number(portfolio.cash) || 0);
  const totalInvested = Object.values(valuesByCode).reduce((sum, value) => sum + value, 0);
  const totalAssets = totalInvested + cash;
  const currentWeights = Object.fromEntries(ASSET_CODES.map((code) => [
    code, totalAssets > 0 ? valuesByCode[code] / totalAssets : 0,
  ])) as Record<AssetCode, number>;
  ASSET_CODES.forEach((code) => { rows[code] = { ...rows[code], weight: totalAssets > 0 ? currentWeights[code] : null }; });
  const equities = assets.filter((asset) => asset.assetClass === 'EQUITY').map((asset) => asset.code);
  const defense = assets.filter((asset) => asset.assetClass !== 'EQUITY').map((asset) => asset.code);
  const unavailable = Object.values(rows).some((row) => row.quality === 'UNAVAILABLE' && (portfolio.values[row.code] ?? 0) > 0);
  const estimated = Object.values(rows).some((row) => row.quality === 'ESTIMATED' && (row.value ?? 0) > 0);
  const valuationDates = [...new Set(Object.values(rows)
    .filter((row) => (row.value ?? 0) > 0)
    .map((row) => row.asOf)
    .filter((value): value is string => Boolean(value)))].sort();
  return {
    asOf: valuationDates.at(-1) ?? null,
    valuationDates,
    dateConsistent: valuationDates.length <= 1,
    valuesByCode, rows, totalInvested, cash, totalAssets, currentWeights,
    currentEquity: equities.reduce((sum, code) => sum + currentWeights[code], 0),
    currentDefense: defense.reduce((sum, code) => sum + currentWeights[code], 0),
    cashWeight: totalAssets > 0 ? cash / totalAssets : 0,
    coverage: expectedValue > 0 ? availableValue / expectedValue : 1,
    quality: unavailable ? 'UNAVAILABLE' : estimated ? 'ESTIMATED' : 'CONFIRMED',
    issues,
  };
}

export function calculateDisplayTargetAmounts(
  totalAssets: number,
  assets: Array<Pick<PublicAsset, 'code' | 'confirmedTarget'>>,
  adjustmentCode: AssetCode = '511010',
): DisplayTargetAmounts {
  const amountsByCode = Object.fromEntries(ASSET_CODES.map((code) => [code, 0])) as Record<AssetCode, number>;
  assets.forEach((asset) => {
    amountsByCode[asset.code] = Math.round(totalAssets * asset.confirmedTarget * 100) / 100;
  });
  const roundedTotal = Object.values(amountsByCode).reduce((sum, amount) => sum + amount, 0);
  const roundingAdjustment = Math.round((totalAssets - roundedTotal) * 100) / 100;
  amountsByCode[adjustmentCode] = Math.round((amountsByCode[adjustmentCode] + roundingAdjustment) * 100) / 100;
  return { amountsByCode, roundingAdjustment, adjustmentCode };
}

export function calculatePortfolioProfitLoss(rawPortfolio: LocalPortfolio, valuation: LocalValuation): PortfolioProfitLoss {
  const portfolio = migratePortfolio(rawPortfolio);
  const rows = {} as Record<AssetCode, AssetProfitLoss>;
  let coveredMarketValue = 0;
  let coveredCostBasis = 0;
  let coveredProfit = 0;
  let realizedProfit = 0;
  let income = 0;
  let realizedComplete = true;
  const updateDates: string[] = [];
  ASSET_CODES.forEach((code) => {
    const position = portfolio.positionsByCode?.[code];
    const marketValue = valuation.rows[code].value;
    const cost = position?.remainingCostBasis;
    const declaredStatus = position?.costBasisStatus ?? 'UNAVAILABLE';
    const statusComplete = declaredStatus === 'COMPLETE' || declaredStatus === 'CONFIRMED';
    const statusPartial = declaredStatus === 'PARTIAL' || declaredStatus === 'ESTIMATED';
    const costAvailable = validNonNegative(cost) && statusComplete && marketValue != null;
    const quality: CostBasisStatus = costAvailable
      ? valuation.rows[code].quality === 'CONFIRMED' ? 'COMPLETE' : 'PARTIAL'
      : declaredStatus === 'PENDING_RECONCILIATION' ? 'PENDING_RECONCILIATION' : statusPartial ? 'PARTIAL' : 'UNAVAILABLE';
    const amount = costAvailable ? marketValue - cost : null;
    const returnValue = costAvailable && cost > 0 ? amount! / cost : null;
    const quantity = position?.inputMode === 'QUANTITY' ? position.quantity ?? 0 : 0;
    const averageCost = costAvailable && quantity > 0 ? cost / quantity : null;
    const assetTrades = (portfolio.tradeEvents ?? []).filter((event) => event.code === code);
    const realizedValues = assetTrades.map((event) => event.realizedProfit).filter((value): value is number => value != null && Number.isFinite(value));
    const hasUnknownRealized = assetTrades.some((event) => event.side === 'SELL' && event.realizedProfit == null);
    const assetRealized = hasUnknownRealized ? null : realizedValues.reduce((sum, value) => sum + value, 0);
    if (hasUnknownRealized) realizedComplete = false;
    const assetIncome = (portfolio.incomeEvents ?? []).filter((event) => event.code === code).reduce((sum, event) => sum + event.amount, 0);
    const totalInvestmentProfit = amount != null && assetRealized != null ? amount + assetRealized + assetIncome : null;
    if (assetRealized != null) realizedProfit += assetRealized;
    income += assetIncome;
    if (costAvailable && marketValue > 0) {
      coveredMarketValue += marketValue;
      coveredCostBasis += cost;
      coveredProfit += amount!;
      if (position?.costBasisUpdatedAt) updateDates.push(position.costBasisUpdatedAt);
    }
    rows[code] = {
      code, marketValue, remainingCostBasis: costAvailable ? cost : null, averageCost, amount, returnValue,
      realizedProfit: assetRealized, income: assetIncome, totalInvestmentProfit, quality,
      updatedAt: position?.costBasisUpdatedAt ?? null,
      issue: costAvailable ? (quality === 'PARTIAL' ? '市值为估算' : null)
        : marketValue && marketValue > 0 ? quality === 'PENDING_RECONCILIATION' ? '份额待核对' : quality === 'PARTIAL' ? '成本不完整' : '成本待建立' : null,
    };
  });
  const denominator = valuation.totalInvested;
  const coverage = denominator > 0 ? coveredMarketValue / denominator : 1;
  const statuses = Object.values(rows).filter((row) => (row.marketValue ?? 0) > 0).map((row) => row.quality);
  const quality: CostBasisStatus = statuses.includes('PENDING_RECONCILIATION') ? 'PENDING_RECONCILIATION'
    : statuses.includes('UNAVAILABLE') ? 'UNAVAILABLE' : statuses.includes('PARTIAL') ? 'PARTIAL' : 'COMPLETE';
  const totalProfit = coverage >= 1 - 1e-10 ? coveredProfit : null;
  return {
    rows, coverage, coveredMarketValue, coveredCostBasis, coveredProfit, realizedProfit, income,
    totalProfit,
    totalInvestmentProfit: totalProfit == null || !realizedComplete ? null : totalProfit + realizedProfit + income,
    quality,
    latestCostBasisUpdate: updateDates.sort().at(-1)?.slice(0, 10) ?? null,
  };
}
